<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreOrders {
 public static function scope(PDO $db,array $actor,bool $customer=false):array {
 if($customer)return ['d.user_id=?',[$actor['id']]];
 if(StoreAccess::allows($db,$actor,'orders')||StoreAccess::allows($db,$actor,'finance'))return ['1=1',[]];
 if(StoreAccess::allows($db,$actor,'design'))return ["EXISTS(SELECT 1 FROM order_items si JOIN store_item_details sd ON sd.item_id=si.id WHERE si.order_id=o.id AND sd.assigned_user_id=?)",[$actor['id']]];
 if(StoreAccess::allows($db,$actor,'production')||StoreAccess::allows($db,$actor,'shipping'))return ["EXISTS(SELECT 1 FROM order_items si JOIN store_item_details sd ON sd.item_id=si.id WHERE si.order_id=o.id AND sd.delivery<>'digital') AND EXISTS(SELECT 1 FROM payments sp WHERE sp.order_id=o.id AND sp.status='verified')",[]];throw new HttpError(403,'مجوز مشاهده سفارش‌ها را ندارید.');
 }
 public static function where(PDO $db,array $actor,array $f,bool $customer=false):array {[$scope,$args]=self::scope($db,$actor,$customer);$w=[$scope];foreach(['id'=>'o.id','status'=>'o.status','payment'=>'p.status','phone'=>'o.phone','designer'=>'ix.assigned_user_id','product'=>'ix.product_id','delivery'=>'ix.delivery','production'=>'ix.production','item_status'=>'ix.status'] as $key=>$col)if(($f[$key]??'')!==''){$val=Security::text($f,$key,80);if(str_starts_with($col,'ix.'))$w[]='EXISTS(SELECT 1 FROM order_items ii JOIN store_item_details ix ON ix.item_id=ii.id WHERE ii.order_id=o.id AND '.$col.'=?)';else $w[]=$col.'=?';$args[]=$val;}
 if(($f['category']??'')!==''){$w[]='EXISTS(SELECT 1 FROM order_items ci JOIN store_category_products cp ON cp.product_id=(SELECT product_id FROM variants WHERE id=ci.variant_id) WHERE ci.order_id=o.id AND cp.category_id=?)';$args[]=StoreCatalog::integer($f['category'],1);}if(($f['shipment_status']??'')!==''){$w[]='EXISTS(SELECT 1 FROM store_shipments ss WHERE ss.order_id=o.id AND ss.status=?)';$args[]=Security::text($f,'shipment_status',30);}
 $q=Security::text($f,'q',150,false);if($q!==''){$w[]='(o.customer LIKE ? OR o.phone LIKE ? OR EXISTS(SELECT 1 FROM order_items qi JOIN store_item_details qd ON qd.item_id=qi.id WHERE qi.order_id=o.id AND (qi.title LIKE ? OR qd.snapshot LIKE ?)))';array_push($args,...array_fill(0,4,'%'.$q.'%'));}
 if(($f['period']??'')!==''){ $period=Security::text($f,'period',10);$start=['today'=>date('Y-m-d'),'week'=>date('Y-m-d',time()-6*86400),'month'=>date('Y-m-d',time()-29*86400)][$period]??null;if(!$start)throw new HttpError(422,'بازه سریع معتبر نیست.');$f['from']=$f['from']??$start;$f['to']=$f['to']??date('Y-m-d');}if(!empty($f['overdue'])&&StoreOperationsSchema::ready($db)){$w[]="EXISTS(SELECT 1 FROM order_items di JOIN store_item_schedule ds ON ds.item_id=di.id JOIN store_item_details dd ON dd.item_id=di.id WHERE di.order_id=o.id AND ds.due_at<? AND ds.completed_at IS NULL AND dd.status NOT IN('cancelled','returned','completed'))";$args[]=date('Y-m-d H:i:s');}
 foreach(['from'=>'>=','to'=>'<='] as $k=>$op)if(($f[$k]??'')!==''){$date=Security::text($f,$k,10);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))throw new HttpError(422,'تاریخ فیلتر معتبر نیست.');$w[]='o.created_at'.$op.'?';$args[]=$date.($k==='to'?' 23:59:59':' 00:00:00');}
 foreach(['min_total'=>'>=','max_total'=>'<='] as $k=>$op)if(($f[$k]??'')!==''){$w[]='o.total'.$op.'?';$args[]=StoreCatalog::integer($f[$k],0,2000000000);}
 foreach(['province','city'] as $key)if(($f[$key]??'')!==''){$w[]='d.payload LIKE ?';$args[]='%'.Security::text($f,$key,150).'%';}return [implode(' AND ',$w),$args];
 }
 public static function listing(PDO $db,array $actor,array $f,bool $customer=false,int $per=24):array {
 [$w,$args]=self::where($db,$actor,$f,$customer);$from=' FROM orders o JOIN store_order_details d ON d.order_id=o.id LEFT JOIN payments p ON p.order_id=o.id WHERE '.$w;$count=(int)Db::query($db,'SELECT COUNT(*)'.$from,$args)->fetchColumn();$page=max(1,min(max(1,(int)ceil($count/$per)),(int)($f['p']??1)));$rows=Db::query($db,'SELECT o.*,p.status AS payment_status'.$from.' ORDER BY o.id DESC LIMIT '.$per.' OFFSET '.(($page-1)*$per),$args)->fetchAll();$financial=$customer||StoreAccess::allows($db,$actor,'orders')||StoreAccess::allows($db,$actor,'finance');if(!$financial)foreach($rows as &$r)foreach(['subtotal','discount','shipping','total','phone','postal_code','address'] as $key)if(!StoreAccess::allows($db,$actor,'shipping')||!in_array($key,['phone','postal_code','address'],true))unset($r[$key]);unset($r);return ['items'=>$rows,'count'=>$count,'page'=>$page,'per'=>$per,'pages'=>(int)ceil($count/$per)];
 }
 public static function get(PDO $db,array $actor,int $id):array {
 [$scope,$args]=self::scope($db,$actor,StoreAccess::owner($db,$id,$actor));$o=Db::query($db,'SELECT o.*,d.user_id,d.currency,d.tax,d.payload,d.reservation_state,d.expires_at FROM orders o JOIN store_order_details d ON d.order_id=o.id WHERE o.id=? AND '.$scope,[$id,...$args])->fetch();if(!$o)throw new HttpError(404,'سفارش پیدا نشد.');$owner=StoreAccess::owner($db,$id,$actor);$manager=StoreAccess::allows($db,$actor,'orders');$finance=StoreAccess::allows($db,$actor,'finance');$shipping=StoreAccess::allows($db,$actor,'shipping');$design=StoreAccess::allows($db,$actor,'design')&&!$manager;
 $items=Db::query($db,'SELECT i.*,d.* FROM order_items i JOIN store_item_details d ON d.item_id=i.id WHERE i.order_id=?'.($design?' AND d.assigned_user_id=?':''),$design?[$id,$actor['id']]:[$id])->fetchAll();$ids=array_column($items,'item_id');
 foreach($items as &$i){$i['data']=Protocol::decode($i['snapshot']);$i['schedule']=StoreOperationsSchema::ready($db)?(Db::query($db,'SELECT * FROM store_item_schedule WHERE item_id=?',[$i['item_id']])->fetch()?:[]):[];$i['production_records']=StoreOperationsSchema::ready($db)?Db::query($db,'SELECT * FROM store_production_records WHERE item_id=? ORDER BY id DESC',[$i['item_id']])->fetchAll():[];$i['files']=Db::query($db,'SELECT id,kind,filename,mime FROM store_files WHERE item_id=? AND active=1',[$i['item_id']])->fetchAll();$i['proofs']=$i['approval_required']?Db::query($db,'SELECT * FROM store_proofs WHERE item_id=? ORDER BY version DESC',[$i['item_id']])->fetchAll():[];$i['history']=Db::query($db,'SELECT * FROM store_item_history WHERE item_id=? ORDER BY id DESC',[$i['item_id']])->fetchAll();if(!$owner&&!$manager&&!$finance){unset($i['price'],$i['data']['base_price']);}}
 unset($i);$messages=Db::query($db,'SELECT * FROM store_messages WHERE order_id=?'.($owner?' AND internal=0':'').' ORDER BY id',[$id])->fetchAll();if($design)$messages=array_values(array_filter($messages,fn($m)=>in_array($m['item_id'],$ids)||$m['item_id']===null&&$m['internal']==0));
 $shipments=($owner||$manager||$shipping||$finance)?Db::query($db,'SELECT * FROM store_shipments WHERE order_id=? ORDER BY id',[$id])->fetchAll():[];
 $payment=($owner||$manager||$finance)?Db::query($db,'SELECT * FROM payments WHERE order_id=?',[$id])->fetch():null;
 $attempts=($owner||$manager||$finance)?Db::query($db,'SELECT * FROM store_payment_attempts WHERE order_id=? ORDER BY id DESC',[$id])->fetchAll():[];$refunds=($owner||$manager||$finance)?Db::query($db,'SELECT * FROM store_refunds WHERE order_id=? ORDER BY id',[$id])->fetchAll():[];
 if(!$owner&&!$manager&&!$finance){foreach(['subtotal','discount','shipping','total','tax'] as $k)unset($o[$k]);if(!$shipping)foreach(['customer','phone','address','postal_code','payload'] as $k)unset($o[$k]);}
 return compact('o','items','messages','shipments','payment','attempts','refunds','owner','manager','finance','shipping','design');
 }
 public static function quote(PDO $db,array $actor,int $variant,int $quantity,array $input):int {MemberServices::requireMember($db,$actor);[$p,$v]=StoreCart::product($db,$variant);if($p['pricing']!=='quote'||$quantity<1||$quantity>99)throw new HttpError(422,'این کالا استعلامی نیست یا تعداد معتبر نیست.');$data=StoreForms::validate($db,StoreForms::forProduct($db,$p),$input,StoreCart::token($db,$actor));return Db::insert($db,'store_quotes',['user_id'=>$actor['id'],'variant_id'=>$variant,'quantity'=>$quantity,'payload'=>Protocol::encode($data),'status'=>'requested','created_at'=>date(DATE_ATOM)]);}
 public static function offer(PDO $db,array $actor,int $id,int $amount,int $expires,string $note):void {StoreAccess::require($db,$actor,'orders');StoreAccess::money($amount);if($amount<1||$expires<time())throw new HttpError(422,'مبلغ یا اعتبار پیشنهاد معتبر نیست.');$q=Db::query($db,'SELECT * FROM store_quotes WHERE id=?',[$id])->fetch();if(!$q||$q['order_id'])throw new HttpError(422,'استعلام قابل قیمت‌گذاری نیست.');Db::query($db,"UPDATE store_quotes SET amount=?,expires_at=?,status='offered' WHERE id=?",[$amount,$expires,$id]);StoreAccess::audit($db,$actor,'quote.offer','quote',$id,['amount'=>$q['amount']],['amount'=>$amount,'expires_at'=>$expires],$note);}
 public static function cancelPending(PDO $db,array $actor,int $id,string $reason):void {Db::transaction($db,function()use($db,$actor,$id,$reason){$o=Db::query($db,'SELECT * FROM orders WHERE id=?'.StoreAccess::lock($db),[$id])->fetch();if(!$o||(!StoreAccess::owner($db,$id,$actor)&&!StoreAccess::allows($db,$actor,'orders')))throw new HttpError(404,'سفارش پیدا نشد.');if(!in_array($o['status'],['pending','payment_failed','expired'],true)||trim($reason)==='')throw new HttpError(422,'لغو مستقیم فقط برای سفارش پرداخت‌نشده با علت ممکن است.');StoreCheckout::release($db,$o,$actor);Db::query($db,"UPDATE orders SET status='cancelled' WHERE id=?",[$id]);Db::query($db,"UPDATE store_payment_attempts SET status='cancelled' WHERE order_id=? AND status='pending'",[$id]);StoreAccess::audit($db,$actor,'order.cancel','order',$id,[],[],$reason);});}
}
